inline ip6_t mask_address(const ip6_t& a, int len) {
    ip6_t r = a;
    if (len >= 128) return r;
    if (len == 64) { r.lo = 0; return r; }
    if (len > 64) { int s = 128 - len; r.lo = (r.lo >> s) << s; return r; }
    if (len <= 0) { r.hi = 0; r.lo = 0; return r; }
    int s = 64 - len;
    r.hi = (r.hi >> s) << s;
    r.lo = 0;
    return r;
}

// Does prefix (a,len) cover the whole region of addresses sharing the first
// `len` bits with b?  (i.e. is (a,len) a prefix of (b,*).)
inline bool same_prefix(const ip6_t& a, const ip6_t& b, int len) {
    ip6_t ma = mask_address(a, len);
    ip6_t mb = mask_address(b, len);
    return ma.hi == mb.hi && ma.lo == mb.lo;
}

inline uint64_t count_ones_before(uint64_t bm, int pos) {
    if (pos <= 0) return 0;
    if (pos >= 64) return (uint64_t)__builtin_popcountll(bm);
    return (uint64_t)__builtin_popcountll(bm & ((1ULL << pos) - 1));
}

inline int floor_log2(uint64_t v) { return 63 - __builtin_clzll(v); }

// origin (forest owner) length bounds: 0..16 / 17..64 / 65..128
inline bool origin_len_ok(int origin, int len) {
    if (origin == 0) return len >= 0 && len <= 16;
    if (origin == FRONT16_BITS) return len >= 17 && len <= 64;
    return len >= 65 && len <= 128;
}

